157	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
158	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
159	    if (state.priv == 2 || state.priv > 3)
160	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
161	
162	    // dmactive must transition 0->1 in its own write before any other
163	    // DMCONTROL bit is honored (RISC-V Debug Spec).
164	    bus_.write(kDmcontrol, kDmcontrolDmactive);
165	    request_halt();
166	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
167	
168	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
169	    // accepted (FS or VS == Off disables the extension and the hart NACKs
170	    // the writes). The drained state.mstatus may legitimately carry FS or
171	    // VS at Off (e.g. an OS context-switched the regs away before the
172	    // trigger fired) -- gating the write on the drained field skips the
173	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
174	    // write mstatus when either extension is in scope; force-OR Initial
175	    // when the drained field is Off. This enable is local to the vsim
176	    // phase; the state.mstatus written to the handoff file is left
177	    // unmodified.
178	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
179	      uint64_t enable_mstatus = state.mstatus;
180	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
181	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
182	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
183	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
184	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
185	    }
186	
187	    // FPR restore (requires mstatus.FS enabled above). The block-load (opt-in)
188	    // sweeps f0..f31 from the scratch page via a PB fld-sweep -- ~6 halted-hart
189	    // round-trips instead of 32 abstract writes -- when the V region leaves room;
190	    // otherwise fall back to per-register abstract writes. Its integer base x5 is
191	    // re-staged by the V sweep and restored by the GPR loop below, so it is safe
192	    // to clobber here.
193	    if (state.flags & HYBRID_FLAG_FP) {
194	      // LG2: elide the whole FPR block when every f-reg already holds the
195	      // engine's reset value -- the reload would rewrite what is there.
196	      const bool fpr_equal = has_baseline_
197	        && std::memcmp(state.fpr, baseline_.fpr, sizeof state.fpr) == 0;
198	      if (fpr_equal) {
199	        baseline_skip_count_ += 32;
200	      } else if (fpr_block_load_ && scratch_gpa_ != kVScratchGpaUnset
201	                 && fpr_scratch_fits(state.vlenb)) {
202	        restore_fprs_via_pb(fpr_scratch_gpa(scratch_gpa_));
203	      } else {
204	        for (uint16_t i = 0; i < 32; ++i)
205	          write_64bit_register(regno_fpr(i), state.fpr[i]);
206	      }
207	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
208	      // fallback scratch x5 is overwritten by the GPR loop below.
209	      if (!baseline_skips(state.fcsr, baseline_.fcsr))
210	        write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
211	    }
212	
213	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
214	    // the GPR loop overwrites x5 afterward so state is preserved).
215	    if (state.flags & HYBRID_FLAG_V) {
216	      // V data regfile: reload v0..v31 from the shared scratch region via the
217	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
218	      // because the sweep's own vsetvl (e8/m8) clobbers vtype/vl/vstart, which
219	      // the restore then overwrites with the architectural values. The sweep
220	      // uses x5/x6/x7 as scratch (x7 is the group base pointer); the GPR loop
221	      // below restores all three. The scratch is vlenb-packed
222	      // (stage_v_to_scratch), so the sweep takes only the runtime vlenb.
223	      if (scratch_gpa_ == kVScratchGpaUnset)
224	        throw std::runtime_error(
225	          "ResumeDriver::resume: V state present but scratch GPA unset");
226	      // LG2: elide the reload sweep when every v-reg already holds the
227	      // engine's reset bytes.
228	      const bool v_data_equal = has_baseline_
229	        && std::memcmp(state.vreg, baseline_.vreg, sizeof state.vreg) == 0;
230	      if (v_data_equal)
231	        baseline_skip_count_ += 32;
232	      else
233	        pb_v_data_sweep(bus_, scratch_gpa_, state.vlenb, /*load=*/true);
234	
235	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
236	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
237	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
238	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
239	      // LG2 clobber rule: the data sweep's own vsetvl overwrote vtype/vl/
240	      // vstart, so baseline equality only proves this vsetvl redundant when
241	      // the sweep did NOT run.
242	      const bool vcfg_equal = v_data_equal && v_cfg_at_reset_
243	        && state.vl == baseline_.vl && state.vtype == baseline_.vtype;
244	      if (vcfg_equal) {
245	        ++baseline_skip_count_;  // the elided vsetvl exec
246	      } else {
247	        write_64bit_register(regno_gpr(5), state.vl);
248	        write_64bit_register(regno_gpr(6), state.vtype);
249	        const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
250	        exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
251	      }
252	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0 -- so its
253	      // baseline skip is likewise only valid when no vsetvl executed.
254	      if (!(vcfg_equal && baseline_skips(state.vstart, baseline_.vstart)))
255	        write_csr_abstract_or_pb(kCsrVstart, state.vstart);
256	      if (!baseline_skips(state.vxsat, baseline_.vxsat))
257	        write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
258	      if (!baseline_skips(state.vxrm, baseline_.vxrm))
259	        write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
260	      if (!baseline_skips(state.vcsr, baseline_.vcsr))
261	        write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
262	    }
263	
264	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
265	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
266	    // in the drained privilege; M-mode states skip the write (prv already 3).
267	    // Before the GPR loop: a PB fallback would clobber scratch x5.
268	    if (state.priv != 3) {
269	      // L2 slice: with PMP implemented and no matching entry, every S/U
270	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
271	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
272	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
273	      // RV64. Tolerant writes: entries beyond what the hart implements
274	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
275	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
276	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
277	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
278	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
279	
280	      const uint64_t dcsr =
281	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
282	      write_csr_abstract_or_pb(kCsrDcsr,
283	                               (dcsr & ~uint64_t{0x3}) | state.priv);
284	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
285	      // silently measure the ROI in the wrong privilege. Verify and abort.
286	      const uint64_t got =
287	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
288	        & 0x3u;
289	      if (got != state.priv)
290	        throw std::runtime_error(
291	          "ResumeDriver::resume: engine does not implement privilege level "
292	          + std::to_string(state.priv)
293	          + " (dcsr.prv pinned to " + std::to_string(got)
294	          + "); pick an S/U-capable engine");
295	    }
296	
297	    // Andes V5 + M-ext CSR restore (abstract-only, LG1-gated). See
298	    // restore_andes_m_ext.
299	    restore_andes_m_ext(state);
300	
301	    // v5: L2C MMIO config restore. Runs BEFORE the GPR loop (like the V sweep):
302	    // it stages an address + value into scratch GPRs x5/x6 and the GPR loop
303	    // below overwrites them with their architectural values, so the clobber is
304	    // safe. It CANNOT run after the loop, where every GPR already holds its
305	    // final value. See restore_l2c.
306	    restore_l2c(state);
307	
308	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite). The
309	    // block-load (opt-in) sweeps x1..x31 from the scratch page via the Program
310	    // Buffer -- ~4 DM round-trips instead of 31 abstract writes -- when the V
311	    // region leaves room; otherwise fall back to per-register abstract writes.
312	    if (gpr_block_load_ && scratch_gpa_ != kVScratchGpaUnset
313	        && gpr_scratch_fits(state.vlenb)) {
314	      restore_gprs_via_pb(gpr_scratch_gpa(scratch_gpa_));
315	    } else {
316	      for (uint16_t i = 1; i < 32; ++i)
317	        write_64bit_register(regno_gpr(i), state.gpr[i]);
318	    }
319	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
320	
321	    write_csr_tolerant_gated(kCsrMtvec, state.mtvec, baseline_.mtvec);
322	
323	    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
324	    // register with no hardware side effects, legal to use inside a trap-free
325	    // ROI. Restore it so a value stashed before the handoff survives into the
326	    // vsim phase.
327	    write_csr_tolerant_gated(kCsrMscratch, state.mscratch, baseline_.mscratch);
328	
329	    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
330	    // interrupt-free ROI envelope these are ordinary read/write registers, so a
331	    // value stashed before the handoff must survive into the vsim phase (same
332	    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
333	    // hardware-driven pending bits, or mtval on a core that hardwires it)
334	    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
335	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
336	    write_csr_tolerant_gated(kCsrMepc,   state.mepc,   baseline_.mepc);
337	    write_csr_tolerant_gated(kCsrMcause, state.mcause, baseline_.mcause);
338	    write_csr_tolerant_gated(kCsrMtval,  state.mtval,  baseline_.mtval);
339	    write_csr_tolerant_gated(kCsrMie,    state.mie,    baseline_.mie);
340	    write_csr_tolerant_gated(kCsrMip,    state.mip,    baseline_.mip);
341	
342	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
343	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
344	    // caches) but has no cache model, so without this the cycle engine resumes
345	    // at the ROI with caches at their reset default -- DISABLED -- and the
346	    // whole measured window runs uncached, inflating it severalfold. Tolerant
347	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
348	    // write as a no-op, and a drained 0 (caches were off) restores the reset
349	    // state, so this is always safe to issue.
350	    if (wm_live(state, HYBRID_WM_MCACHE_CTL))
351	      write_csr_tolerant_gated(kCsrMcacheCtl, state.mcache_ctl,
352	                               baseline_.mcache_ctl);
353	    if (wm_live(state, HYBRID_WM_MMISC_CTL))
354	      write_csr_tolerant_gated(kCsrMmiscCtl,  state.mmisc_ctl,
355	                               baseline_.mmisc_ctl);
356	
357	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
358	    // from QEMU1's drain value. Without this, vsim's local counter starts
359	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
360	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
361	    // overwrite here as the GPR loop already ran.
362	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
363	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
364	
365	    clear_cmderr_if_set();
366	    request_resume();
367	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
368	                   "ResumeDriver resume");
369	  }
