371	private:
372	  void request_halt()
373	  {
374	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
375	  }
376	
377	  void request_resume()
378	  {
379	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
380	  }
381	
382	  void write_64bit_register(uint16_t regno, uint64_t value)
383	  {
384	    write_register_abstract(bus_, regno, value);
385	  }
386	
387	  // GPR block-load: reload x1..x31 from the scratch page via a PB ld-sweep. Base
388	  // x31 rides the sweep last (it is the base pointer). x31's slot is the
389	  // mapping's final word, which the memory decoder now returns correctly.
390	  void restore_gprs_via_pb(uint64_t gpr_gpa)
391	  {
392	    pb_block_sweep(bus_, 31, gpr_gpa, 1, 32, &encode_ld);
393	  }
394	
395	  // FPR block-load: reload f0..f31 from the scratch page via a PB fld-sweep,
396	  // integer base x5 (a caller-saved scratch the GPR loop restores later). No
397	  // f-reg is the base, so all 32 ride the sweep (first_reg = 0).
398	  void restore_fprs_via_pb(uint64_t fpr_gpa)
399	  {
400	    pb_block_sweep(bus_, 5, fpr_gpa, 0, 32, &encode_fld);
401	  }
402	
403	  // v5: write back the WRITABLE boot-static L2C config registers via
404	  // Program-Buffer word stores. The L2C block is MMIO, not a CSR, so each write
405	  // is `sw x5, 0(x6)` with the register address staged in x6 and the value (low
406	  // word) in x5. Restores ONLY the config registers the ROI can hold as plain
407	  // state: Control (CEN/prefetch/ECC/RAM timing), HPM Control, Way Allocation
408	  // Masks. The read-only Configuration Register, the side-effecting CCTL command
409	  // registers (writing one re-issues an L2 cache op), and the write-1-clear
410	  // error registers are captured in the record but NEVER written back.
411	  //
412	  // Hard-gated on the engine having an L2C (l2c_present_): a store to an absent
413	  // L2C region faults the Program Buffer, so unlike a tolerant CSR write this
414	  // must issue nothing on a core without an L2C. x5/x6 are safe scratch here --
415	  // the caller runs this before the GPR loop, which overwrites both.
416	  void restore_l2c(const hybrid_state_v1& state)
417	  {
418	    if (!(state.flags & HYBRID_FLAG_L2C)) return;
419	    if (!l2c_present_) return;
420	
421	    pb_store_l2c_reg(HYBRID_L2C_OFF_CONTROL,
422	                     state.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8]);
423	    pb_store_l2c_reg(HYBRID_L2C_OFF_HPM_CTL0,
424	                     state.l2c.reg[HYBRID_L2C_OFF_HPM_CTL0 / 8]);
425	    for (uint32_t i = 0; i < HYBRID_L2C_WAYMASK_NUM; ++i) {
426	      const uint32_t off = HYBRID_L2C_OFF_WAYMASK0 + i * 8u;
427	      pb_store_l2c_reg(off, state.l2c.reg[off / 8]);
428	    }
429	  }
430	
431	  // One L2C register store: stage the MMIO address in x6 and the value's low
432	  // word in x5, then execute `sw x5, 0(x6)` in the Program Buffer. Word store
433	  // per DS220 11.8.3 (single transfer, access size < 8 bytes); all documented
434	  // L2C control bits live in the low 32.
435	  void pb_store_l2c_reg(uint32_t offset, uint64_t value)
436	  {
437	    write_register_abstract(bus_, regno_gpr(6), l2c_base_ + offset);
438	    write_register_abstract(bus_, regno_gpr(5), value & 0xffffffffu);
439	    const std::array<uint32_t, 1> pb = { encode_sw(5, 6, 0) };
440	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
441	  }
442	
443	  // Andes V5 + M-ext CSR restore: one caps-gated abstract write per CSR
444	  // (pmaaddr before pmacfg, mirroring the PMP restore ordering), each gated by
445	  // the LG1 reset baseline. Abstract-only by design -- a batched Program-Buffer
446	  // sweep can't tolerate a cmderr on one CSR without corrupting the rest of the
447	  // batch (a WARL/read-only CSR faults the whole group mid-sweep), whereas the
448	  // per-CSR abstract path tolerates a single failure and moves on.
449	  void restore_andes_m_ext(const hybrid_state_v1& state)
450	  {
451	    const bool andes = state.flags & HYBRID_FLAG_ANDES;
452	    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
453	    if (!andes && !mext) return;
454	
455	    // Each write is double-gated: caps (the ENGINE implements the CSR) and the
456	    // v6 write-mask (the PRODUCER's guest actually wrote it -- wm_live).
457	    if (andes) {
458	#define X(field, addr, name)                                                  \
459	  if (caps_.supports_csr(addr)                                                \
460	      && wm_live(state, HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_##field))  \
461	    write_csr_tolerant_gated(addr, state.andes.field, baseline_.andes.field);
462	      HYBRID_ANDES_CSR_LIST(X)
463	#undef X
464	      for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
465	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i)
466	            && wm_live(state, HYBRID_WM_PMAADDR_BASE + i))
467	          write_csr_tolerant_gated(HYBRID_PMA_ADDR0_CSR + i,
468	                                   state.andes.pmaaddr[i],
469	                                   baseline_.andes.pmaaddr[i]);
470	      for (uint16_t i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
471	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i)
472	            && wm_live(state, HYBRID_WM_PMACFG_BASE + i))
473	          write_csr_tolerant_gated(HYBRID_PMA_CFG0_CSR + 2 * i,
474	                                   state.andes.pmacfg[i],
475	                                   baseline_.andes.pmacfg[i]);
476	    }
477	    if (mext) {
478	#define X(field, addr, name)                                                  \
479	  if (caps_.supports_csr(addr)                                                \
480	      && wm_live(state, HYBRID_WM_M_EXT_BASE + HYBRID_WM_M_EXT_IDX_##field))  \
481	    write_csr_tolerant_gated(addr, state.m_ext.field, baseline_.m_ext.field);
482	      HYBRID_M_EXT_CSR_LIST(X)
483	#undef X
484	    }
485	  }
486	
487	  // Abstract-first CSR write with Program Buffer fallback.
488	  // Tries an abstract register write; if the DM signals cmderr, clears it,
489	  // stages the value in scratch_gpr via abstract GPR write, then executes a
490	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
491	  // to x5 (t0) which the GPR restore loop overwrites later.
492	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
493	                                 uint8_t scratch_gpr = 5)
494	  {
495	    write_64bit_register(regno_csr(csr), value);
496	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
497	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
498	    write_64bit_register(regno_gpr(scratch_gpr), value);
499	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
500	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
501	  }
502	
503	  // Write a CSR-addressable register and clear any cmderr the DM raised.
504	  // Used for CSRs whose abstract-access support may be implementation
505	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
506	  // remaining writes.
507	  void write_csr_tolerant(uint16_t csr, uint64_t value)
508	  {
509	    write_64bit_register(regno_csr(csr), value);
510	    clear_cmderr_if_set();
511	  }
512	
513	  // v6: true when the handoff says this mask-governed CSR is live -- the
514	  // producer's guest actually wrote it, or the producer carried no mask at all
515	  // (pre-v6 file: restore-everything fallback). An untouched CSR is skipped so
516	  // the engine keeps its OWN reset value: the drained value is only the
517	  // producer's reset default, which may legitimately differ from this RTL's
518	  // (msp_bound all-ones vs 0, milmb.IEN 0 vs 1; see hybrid/write_mask.h).
519	  static auto wm_live(const hybrid_state_v1& state, int slot) -> bool
520	  {
521	    if (!(state.flags & HYBRID_FLAG_WRITE_MASK)) return true;
522	    return hybrid_wm_test(state.write_mask, static_cast<unsigned>(slot)) != 0;
523	  }
524	
525	  // LG1: true (and counted) when the reset baseline marks this write a no-op.
526	  auto baseline_skips(uint64_t value, uint64_t reset_value) -> bool
527	  {
528	    if (!has_baseline_ || value != reset_value) return false;
529	    ++baseline_skip_count_;
530	    return true;
531	  }
532	
533	  // Tolerant CSR write elided when the value already equals the engine's
534	  // reset value (reset_value is only meaningful when the baseline is set;
535	  // baseline_ is zero-initialized otherwise and baseline_skips ignores it).
536	  void write_csr_tolerant_gated(uint16_t csr, uint64_t value,
537	                                uint64_t reset_value)
538	  {
539	    if (baseline_skips(value, reset_value)) return;
540	    write_csr_tolerant(csr, value);
541	  }
542	
543	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
544	  // is rejected until the bits are W1C-cleared. We tolerate per-register
545	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
546	  // error before resuming so the hart isn't left in a stuck state.
547	  // B17: record the last observed non-zero cmderr and a clear count so a
548	  // partially-broken restore is observable via the public accessors
549	  // instead of silently swallowed.
550	  void clear_cmderr_if_set()
551	  {
552	    const auto status = bus_.read(kAbstractcs);
553	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
554	    if (code != 0u) {
555	      last_observed_cmderr_ = code;
556	      ++cmderr_clear_count_;
557	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
558	    }
559	  }
560	
561	  DmiBus& bus_;
562	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
563	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
564	  bool l2c_present_ = false;                  // v5: engine has an L2C (set_l2c)
565	  uint64_t l2c_base_ = 0;                     // v5: L2C MMIO register base
566	  bool gpr_block_load_ = false;               // opt-in GPR PB ld-sweep
567	  bool fpr_block_load_ = false;               // opt-in FPR PB fld-sweep
568	  hybrid_state_v1 baseline_{};                // LG1: engine reset-state drain
569	  bool has_baseline_ = false;                 // baseline_ valid only when set
570	  bool v_cfg_at_reset_ = true;                // false: capture clobbered vcfg
571	  uint64_t baseline_skip_count_ = 0;          // LG1: elided tolerant writes
572	  uint32_t last_observed_cmderr_ = 0;
573	  uint64_t cmderr_clear_count_   = 0;
574	
575	public:
576	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
577	  // at least one abstract write tripped a sticky cmderr the restore
578	  // tolerated by clearing. cmderr_clear_count() is the total number of
579	  // such clears across all calls into clear_cmderr_if_set() this run.
580	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
581	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
582	};
583	
584	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
585	// via an Abstract Command. Halts-and-reads contract: caller must have the
586	// hart in the halted state. Shared by StateDrain (drain at exit). If
587	// abstractcs.cmderr goes sticky after the command, the helper clears it and
588	// reports 0 rather than blocking the caller -- a missing CSR mirrors as zero
589	// instead of corrupting the adjacent field.
590	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
591	                                     const char* poll_label
592	                                       = "read_register_64")
593	  -> std::optional<uint64_t>
594	{
595	  using RD = ResumeDriver;
596	  bus.write(RD::kCommand,
597	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
598	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
599	  const auto status = bus.read(RD::kAbstractcs);
600	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
601	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
602	    return std::nullopt;
603	  }
604	  const uint64_t lo = bus.read(RD::kData0);
605	  const uint64_t hi = bus.read(RD::kData1);
606	  return lo | (hi << 32);
607	}
608	
609	inline auto read_register_64(DmiBus& bus, uint16_t regno,
610	                             const char* poll_label = "read_register_64")
611	  -> uint64_t
612	{
613	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
614	}
615	
616	}  // namespace hybrid
