    return false;
  };

  // (a) x1..x31 are all reloaded via ld in the Program Buffer -- x31 too, now
  //     that the memory-decoder fix makes its final-word slot readable. x31 is
  //     the base pointer, so its own ld is the last one executed.
  int found = 0;
  for (uint8_t k = 1; k < 32; ++k)  // k=31 (x31, the base) rides the sweep too
    if (in_progbuf(hybrid::encode_ld(k, 31, static_cast<int32_t>((k - 1) * 8))))
      ++found;
  CHECK(found == 31);

  // (b) exactly ONE GPR abstract write to x31: it seeds the base pointer with
  //     the scratch GPA. x31's architectural value now arrives via its own ld
  //     (last in the sweep), so there is no second abstract write. No other GPR
  //     uses an abstract write (x1..x31 all come via ld).
  const uint64_t gpr_gpa = hybrid::gpr_scratch_gpa(kScratch);
  std::vector<uint64_t> x31_writes;
  int nonx31_gpr_writes = 0;
  for (std::size_t i = 2; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
    const uint16_t rn = static_cast<uint16_t>(op.value & 0xFFFFu);
    if (!((op.value >> 16) & 1u)) continue;
    if (rn == hybrid::regno_gpr(31))
      x31_writes.push_back((uint64_t(bus.ops[i - 1].value) << 32)
                           | bus.ops[i - 2].value);
    else if (rn > hybrid::regno_gpr(0) && rn <= hybrid::regno_gpr(30))
      ++nonx31_gpr_writes;
  }
  REQUIRE(x31_writes.size() == 1u);
  CHECK(x31_writes.front() == gpr_gpa);            // base seed only
  CHECK(nonx31_gpr_writes == 0);

  // (c) with progbufsize=8 (7 loads/execution) the 31 loads take 5 Program-
  //     Buffer executions (7+7+7+7+3), not 31 abstract writes.
  int execs = 0;
  for (const auto& op : bus.ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && op.value == hybrid::kExecProgbufCmd)
      ++execs;
  CHECK(execs == 5);
}

TEST_CASE("resume with FPR block-load: f0..f31 via PB fld-sweep, base x5 seeded "
          "with the scratch GPA")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);  // halted + resumeack
  bus.abstractcs_value = 8u << 24;              // progbufsize = 8 (this DM)

  auto s = rv64_state(0x80001000, 0);
  s.flags  |= HYBRID_FLAG_FP;
  s.mstatus = 0x6000ULL;  // FS = Dirty: FPRs writable
  for (int i = 0; i < 32; ++i) s.fpr[i] = 0xF0000000ULL + i;
  s.vlenb = 64;  // leaves room for the FPR block beside the V region

  hybrid::ResumeDriver driver(bus, kScratch);
  driver.set_fpr_block_load(true);
  driver.resume(s);

  auto in_progbuf = [&](uint32_t insn) {
    for (const auto& op : bus.ops)
      if (op.kind == DmiOp::Kind::Write && op.reg >= hybrid::kProgbuf0
          && op.reg <= hybrid::kProgbuf0 + hybrid::kProgbufMaxInsns
          && op.value == insn)
        return true;
    return false;
  };

  // (a) f0..f31 are all reloaded via fld in the Program Buffer (base x5). Unlike
  //     GPRs, no f-reg is the base pointer, so all 32 ride the sweep.
  int found = 0;
  for (uint8_t k = 0; k < 32; ++k)
    if (in_progbuf(hybrid::encode_fld(k, 5, static_cast<int32_t>(k * 8))))
      ++found;
  CHECK(found == 32);

  // (b) NO FPR abstract writes: every f-reg arrives via fld, not access-register.
  const auto ns = cmd_regnos(bus.ops);
  for (uint16_t i = 0; i < 32; ++i)
    CHECK_FALSE(contains_regno(ns, hybrid::regno_fpr(i)));

  // (c) an abstract write to x5 seeds the base pointer with the FPR scratch GPA.
  //     (x5 is later overwritten by the abstract GPR loop -- both writes exist;
  //     this checks the seed value is present.)
  const uint64_t fpr_gpa = hybrid::fpr_scratch_gpa(kScratch);
  bool base_seed_found = false;
  for (std::size_t i = 2; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
    if (!((op.value >> 16) & 1u)) continue;  // write bit
    if (static_cast<uint16_t>(op.value & 0xFFFFu) != hybrid::regno_gpr(5))
      continue;
    const uint64_t v =
        (uint64_t(bus.ops[i - 1].value) << 32) | bus.ops[i - 2].value;
    if (v == fpr_gpa) base_seed_found = true;
  }
  CHECK(base_seed_found);

  // (d) with progbufsize=8 (7 loads/execution) the 32 loads take 5 Program-
  //     Buffer executions (7+7+7+7+4), not 32 abstract writes.
  int execs = 0;
  for (const auto& op : bus.ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && op.value == hybrid::kExecProgbufCmd)
      ++execs;
  CHECK(execs == 5);
}

