TEST_CASE("#1 gpr block-store: drain sweeps x1..x30 via a PB sd-sweep, base x31 "
          "seeded with the scratch GPA + captured, no per-GPR abstract reads")
{
  RecordingBus bus;
  bus.dmstatus_value   = kDmstatusHaltedAndAcked;
  bus.abstractcs_value = 8u << 24;  // progbufsize = 8 (batch 7 stores/exec)
  // The base-capture abstract read of x31 must land in state.gpr[31].
  bus.regfile[hybrid::regno_gpr(31)] = 0xBADD1E5111111111ULL;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64;
  input.priv    = 3;
  input.vlenb   = 64;  // gpr_scratch_fits(64)

  hybrid::StateDrain drain(bus, kScratch);
  drain.set_gpr_block_store(true);
  const auto state = drain.drain_with_passthrough(input);

  // (a) x1..x30 stored via encode_sd(k, 31, (k-1)*8) in the Program Buffer.
  for (uint8_t k = 1; k < 31; ++k)
    CHECK(progbuf_has(bus.ops, hybrid::encode_sd(k, 31, (k - 1) * 8)));
  // x31 is the base pointer, so it is NOT swept (seeding destroyed its value).
  CHECK_FALSE(progbuf_has(bus.ops, hybrid::encode_sd(31, 31, 30 * 8)));

  // (b) base pointer x31 seeded with the GPR scratch GPA (value staged in DATA0).
  CHECK(data0_staged(bus.ops, hybrid::gpr_scratch_gpa(kScratch)));

  // (c) x31 captured via abstract read BEFORE the seed: its pre-seed value.
  CHECK(state.gpr[31] == 0xBADD1E5111111111ULL);

  // (d) NO abstract READ command for x1..x30 -- they rode the sweep.
  for (const auto& op : bus.ops) {
    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
    const bool is_read   = ((op.value >> 16) & 1u) == 0u;
    const uint16_t regno = op.value & 0xFFFFu;
    if (is_read && regno >= hybrid::regno_gpr(1) && regno <= hybrid::regno_gpr(30))
      CHECK_FALSE(is_read);  // fail loudly on any per-GPR abstract read
  }
}

