TEST_CASE("#1 block-store fit-gate: a full V page (vlenb too big) falls back to "
          "per-GPR abstract reads, issues no sd-sweep")
{
  RecordingBus bus;
  bus.dmstatus_value   = kDmstatusHaltedAndAcked;
  bus.abstractcs_value = 8u << 24;
  for (uint16_t i = 1; i < 32; ++i)
    bus.regfile[hybrid::regno_gpr(i)] = 0xC0000000ULL + i;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64;
  input.priv    = 3;
  input.vlenb   = 128;  // !gpr_scratch_fits(128): V region fills the page

  hybrid::StateDrain drain(bus, kScratch);
  drain.set_gpr_block_store(true);  // enabled, but the gate forces the fallback
  const auto state = drain.drain_with_passthrough(input);

  // Abstract path: all 31 GPRs read from the DM, no sd in the Program Buffer.
  for (int i = 1; i < 32; ++i)
    CHECK(state.gpr[i] == 0xC0000000ULL + uint64_t(i));
  for (uint8_t k = 1; k < 31; ++k)
    CHECK_FALSE(progbuf_has(bus.ops, hybrid::encode_sd(k, 31, (k - 1) * 8)));
}

